func (m routineGroupMods) WithoutGroupExercisesRoutines() RoutineGroupMod {
	return RoutineGroupModFunc(func(ctx context.Context, o *RoutineGroupTemplate) {
		o.r.GroupExercisesRoutines = nil
	})
}
